import 'dart:convert';
import 'package:projeto_atlas/core/network/atlas_http_client.dart';
import 'package:projeto_atlas/features/animal_health/domain/models/animal_health_data.dart';
import 'package:shared_preferences/shared_preferences.dart';
class AnimalHealthStorageService {final SharedPreferencesAsync _preferences=SharedPreferencesAsync();final AtlasHttpClient _http=AtlasHttpClient();String _n(String v)=>v.trim().toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'),'_');String _key(String f,String g,String a)=>'atlas_animal_health_${_n(f)}_${_n(g)}_${_n(a)}';
Future<List<AnimalHealthData>> loadRecords({required String farmName,required String groupName,required String animalId,String farmId=''})async{final k=_key(farmName,groupName,animalId);if(farmId.isNotEmpty){try{final r=await _http.send('GET','/livestock/health?farm_id=$farmId&animal_id=$animalId');final items=r.asMapList().map(AnimalHealthData.fromMap).toList();await _preferences.setString(k,jsonEncode(items.map((e)=>e.toMap()).toList()));return items;}catch(_){}}final raw=await _preferences.getString(k);if(raw==null||raw.isEmpty)return[];try{return(jsonDecode(raw)as List).map((e)=>AnimalHealthData.fromMap(Map<String,dynamic>.from(e))).toList();}catch(_){return[];}}
Future<List<AnimalHealthData>> saveRecords({required String farmName,required String groupName,required String animalId,required List<AnimalHealthData> records,String farmId='',String lotId=''})async{final k=_key(farmName,groupName,animalId);final out=<AnimalHealthData>[];for(final record in records){if(record.synced||farmId.isEmpty){out.add(record);continue;}try{final r=await _http.send('POST','/livestock/health',body:record.toApi(farmId:farmId,animalId:animalId,lotId:lotId.isEmpty?null:lotId));out.add(AnimalHealthData.fromMap(r.asMap()));}catch(_){out.add(record);}}await _preferences.setString(k,jsonEncode(out.map((e)=>e.toMap()).toList()));return out;} }
